import {accepted,demand} from './operations.js';
import {approvalStatus} from './projects.js';
import {readinessIssues,completedQuantity,readinessException,overdueDays} from './manufacturing.js';
import {STATUSES} from './model.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function shopBoard(parts,dateLabel,{canMove=false}={}){
 return `<div class="shop-board">${STATUSES.map((stage,index)=>{
  const rows=parts.filter(p=>p.status===stage).sort((a,b)=>Number(b.blocked)-Number(a.blocked)||Number(overdueDays(b)>0)-Number(overdueDays(a)>0)||Number(b.priority==='High')-Number(a.priority==='High')||(a.due||'9999').localeCompare(b.due||'9999'));
  const next=STATUSES[index+1],action=['Start preparing','Start cutting','Start finishing','Finish remaining'][index];
  return `<section class="shop-lane lane-${index}" data-drop-stage="${stage}" aria-label="${stage}"><h3><span>${stage}</span><span class="lane-count">${rows.length}</span></h3><div class="shop-lane-cards">${rows.length?rows.map(p=>`<article data-part-id="${escape(p.id)}" class="shop-card ${canMove?'is-movable':''} ${p.blocked?'is-blocked':''} ${overdueDays(p)?'is-overdue':''} ${readinessException(p)?'has-readiness-exception':''}"><div class="card-top">${canMove?`<button type="button" class="part-drag-handle" data-drag-handle aria-label="Move ${escape(p.name)} to another stage" title="Drag to move, or click to choose a stage"><svg viewBox="0 0 16 24" width="12" height="20" aria-hidden="true" focusable="false"><g fill="currentColor"><circle cx="5" cy="5" r="1.5"/><circle cx="11" cy="5" r="1.5"/><circle cx="5" cy="12" r="1.5"/><circle cx="11" cy="12" r="1.5"/><circle cx="5" cy="19" r="1.5"/><circle cx="11" cy="19" r="1.5"/></g></svg></button>`:''}<span class="part-number">${escape(p.number||'No number')}</span><details class="card-menu"><summary aria-label="More actions for ${escape(p.name)}">···</summary><label>Move to<select data-status="${escape(p.id)}" aria-label="Stage for ${escape(p.name)}">${STATUSES.map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></label></details></div><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="card-tags">${overdueDays(p)?'<span class="overdue-badge">Overdue</span>':''}${readinessException(p)?'<span class="exception-badge">Readiness exception</span>':''}${p.blocked?'<span class="blocked-tag">Blocked</span>':''}${p.priority==='High'?'<span class="priority-tag">High priority</span>':''}</div><div class="card-assignment"><span>${escape(p.owner||p.assignedTo||'Unassigned')}</span><span>Qty ${p.quantity}</span></div>${p.process?`<p class="card-process">${escape(p.process)}</p>`:''}${p.due?`<p class="card-due ${overdueDays(p)?'due-overdue':''}">${overdueDays(p)?'Overdue by '+overdueDays(p)+' day'+(overdueDays(p)===1?'':'s')+' · Due ':'Due '}${escape(dateLabel(p.due))}</p>`:''}${p.blocked&&(p.blockReason||p.notes)?`<p class="shop-note">${escape(p.blockReason||p.notes)}<br>Resolver: ${escape(p.blockOwner||'Needed')} · Next: ${escape(p.blockNext||'Needed')}<br>Blocked since: ${escape(p.blockDate||'Not recorded')}</p>`:''}${readinessException(p)?'<p class="readiness-exception-note">Work is in progress, but readiness checks are incomplete.</p>':''}${stage!=='Finished'?`<button class="readiness-link" data-edit="${escape(p.id)}">${readinessException(p)?'Resolve readiness exception':readinessIssues(p).length?readinessIssues(p)[0]:['Not started','Preparing'].includes(stage)?'Ready to start cutting':'Readiness confirmed'}</button>`:''}<div class="batch-progress"><span>${completedQuantity(p)} good made · ${accepted(p)} accepted / ${p.quantity} required · ${Math.max(0,demand(p)-completedQuantity(p))} left</span><progress max="${demand(p)}" value="${completedQuantity(p)}" aria-label="Finished pieces for ${escape(p.name)}"></progress></div>${stage==='Finishing'&&!readinessException(p)&&completedQuantity(p)<p.quantity?`<button class="secondary piece-action" data-finish-piece="${escape(p.id)}" ${p.blocked?'disabled':''}>Record 1 finished piece</button>`:''}<div class="card-actions">${next?`<button class="shop-action" data-advance="${escape(p.id)}" data-next="${next}">${readinessException(p)?'Resolve readiness':stage==='Preparing'&&readinessIssues(p).length?'Review readiness':action}${stage==='Finishing'&&!readinessException(p)?' ('+(p.quantity-completedQuantity(p))+')':''}</button>`:`<span class="finished-label">${approvalStatus(p)==='approved'?'Approved':'Awaiting admin approval'}</span>`}<button class="block-toggle ${p.blocked?'tag-active':''}" aria-pressed="${Boolean(p.blocked)}" data-block="${escape(p.id)}" aria-label="${p.blocked?'Unblock':'Block'} ${escape(p.name)}">${p.blocked?'Unblock':'Block'}</button></div></article>`).join(''):'<p class="lane-empty">No parts</p>'}</div></section>`;
 }).join('')}</div>`;
}
